<script setup>
import { onMounted, ref, reactive, watch } from 'vue'; import { ElMessage } from 'element-plus'; import { commissionApi } from '../api/modules'; import { useAppStore } from '../stores/app'; import * as XLSX from 'xlsx'
const app=useAppStore();const rules=ref([]),records=ref([]),dialog=ref(false),form=reactive({type:'销售',rate:.01,description:'',condition:'{}'});async function load(){rules.value=await commissionApi.rules();records.value=await commissionApi.records({})};async function save(){await commissionApi.save(form);dialog.value=false;ElMessage.success('提成规则已保存');load()};async function calculate(){await commissionApi.calculate({});ElMessage.success('已重新核算');load()};function exportXlsx(){const ws=XLSX.utils.json_to_sheet(records.value);const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'提成明细');XLSX.writeFile(wb,'提成明细.xlsx')};watch(()=>app.eventVersion,()=>{if(['COMMISSION_UPDATED','REPORT_UPDATED'].includes(app.lastEventType))load()});onMounted(load)
</script>
<template><section class="panel"><div class="page-toolbar"><div class="muted">销售 / 加工 / 回收按业务类型配置</div><div class="inline-actions"><el-button @click="calculate">重新核算</el-button><el-button @click="exportXlsx">导出工资表</el-button><el-button type="primary" @click="dialog=true">新增规则</el-button></div></div><el-table :data="rules"><el-table-column prop="type" label="业务类型"/><el-table-column prop="rate" label="比例"><template #default="s">{{(Number(s.row.rate)*100).toFixed(2)}}%</template></el-table-column><el-table-column prop="description" label="说明"/><el-table-column prop="status" label="状态"/></el-table></section><section class="panel" style="margin-top:16px"><div class="panel-title">提成明细</div><el-table :data="records"><el-table-column prop="real_name" label="员工"/><el-table-column prop="month" label="月份"/><el-table-column prop="sales_amount" label="销售额"/><el-table-column prop="commission_amount" label="提成"/></el-table></section><el-dialog v-model="dialog" title="提成规则"><el-form label-width="90px"><el-form-item label="业务类型"><el-select v-model="form.type"><el-option label="销售" value="销售"/><el-option label="加工" value="加工"/><el-option label="回收" value="回收"/></el-select></el-form-item><el-form-item label="比例"><el-input-number v-model="form.rate" :min="0" :max="1" :step=".01"/></el-form-item><el-form-item label="说明"><el-input v-model="form.description"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></template>
